import javax.swing.JTabbedPane;

public class TabSelectionTracker extends JPanel {

    private final JTabbedPane tabs = new JTabbedPane();
    private final JLabel current = new JLabel("(none)");

    public TabSelectionTracker() {
        tabs.setName("tabs");
        current.setName("current");
        tabs.addTab("Inbox", new JPanel());
        tabs.addTab("Drafts", new JPanel());
        tabs.addTab("Sent", new JPanel());
        add(tabs);
        add(current);
        tabs.addChangeListener(e -> refreshCurrent());
        refreshCurrent();
    }

