public class TabSelectionTrackerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            TabSelectionTracker panel = new TabSelectionTracker();
            java.awt.Component tabsComp = find(panel, "tabs");
            java.awt.Component label = find(panel, "current");
            check("tabbed pane found", true, tabsComp instanceof javax.swing.JTabbedPane);
            if (tabsComp instanceof javax.swing.JTabbedPane) {
                javax.swing.JTabbedPane tabs = (javax.swing.JTabbedPane) tabsComp;
                check("three tabs", 3, tabs.getTabCount());
                check("startup label", "Viewing: Inbox", labelText(label));
                panel.selectTab("Sent");
                check("selectTab picked the right index", 2, tabs.getSelectedIndex());
                check("label after selectTab", "Viewing: Sent", labelText(label));
                panel.selectTab("Trash");
                check("unknown title changes nothing", 2, tabs.getSelectedIndex());
                tabs.setSelectedIndex(1);
                check("label follows a direct selection", "Viewing: Drafts", labelText(label));
            } else {
                failures++;
                System.out.println("FAIL  tabs not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

